                        [Validation(Required=false)]
                        public string Category { get; set; }

                        /// <summary>
                        /// <para>The summary content.</para>
                        /// 
                        /// <b>Example:</b>
                        /// <para>5</para>
                        /// </summary>
                        [NameInMap("Content")]
                        [Validation(Required=false)]
                        public string Content { get; set; }

                        /// <summary>
                        /// <para>The summary name.</para>
                        /// 
                        /// <b>Example:</b>
                        /// <para>score</para>
                        /// </summary>
                        [NameInMap("SummaryName")]
                        [Validation(Required=false)]
                        public string SummaryName { get; set; }

                    }

                    /// <summary>
                    /// <para>The summary creation time. The value is a UNIX timestamp in milliseconds.</para>
                    /// 
                    /// <b>Example:</b>
                    /// <para>1579068424883</para>
                    /// </summary>
                    [NameInMap("Timestamp")]
                    [Validation(Required=false)]
                    public long? Timestamp { get; set; }

                }

                /// <summary>
                /// <para>The dialogue duration. This field is not returned.</para>
                /// <remarks>
                /// <para>This data is returned in the ActionParams parameter of the last dictionary in the Conversation list.</para>
                /// </remarks>
                /// 
                /// <b>Example:</b>
                /// <para>120</para>
                /// </summary>
                [NameInMap("Duration")]
                [Validation(Required=false)]
                public int? Duration { get; set; }

                /// <summary>
                /// <para>The call completion reason. Valid values:</para>
                /// <list type="bullet">
                /// <item><description><b>1</b>: FINISHED (Normal completion).</description></item>
                /// <item><description><b>2</b>: CHATBOT_HANGUP_AFTER_NOANSWER (Robot hung up after unrecognized input).</description></item>
                /// <item><description><b>3</b>: CHATBOT_HANGUP_AFTER_SILENCE (Robot hung up after silence timeout).</description></item>
                /// <item><description><b>4</b>: CLIENT_HANGUP_AFTER_NOANSWER (User hung up after unrecognized input).</description></item>
                /// <item><description><b>5</b>: CLIENT_HANGUP (User hung up without reason).</description></item>
                /// <item><description><b>6</b>: TRANSFER_BY_INTENT (Transferred to human agent due to intent match).</description></item>
                /// <item><description><b>7</b>: TRANSFER_AFTER_NOANSWER (Transferred to human agent after unrecognized input).</description></item>
                /// <item><description><b>8</b>: INO_INTERACTION (No interaction from the user).</description></item>
                /// <item><description><b>9</b>: ERROR (Interrupted by system error).</description></item>
                /// </list>
                /// 
                /// <b>Example:</b>
                /// <para>FINISHED</para>
                /// </summary>
                [NameInMap("EndReason")]
                [Validation(Required=false)]
                public string EndReason { get; set; }

                /// <summary>
                /// <para>The actual end time. The value is a UNIX timestamp in milliseconds.</para>
                /// 
                /// <b>Example:</b>
                /// <para>1579068424883</para>
                /// </summary>
                [NameInMap("EndTime")]
                [Validation(Required=false)]
                public long? EndTime { get; set; }

                /// <summary>
                /// <para>The party that hung up. Valid values:</para>
                /// <list type="bullet">
                /// <item><description>client: The customer.</description></item>
                /// <item><description>ivr: The robot.</description></item>
                /// </list>
                /// 
                /// <b>Example:</b>
                /// <para>client</para>
                /// </summary>
                [NameInMap("HangUpDirection")]
                [Validation(Required=false)]
                public string HangUpDirection { get; set; }

                /// <summary>
                /// <para>The job ID.</para>
                /// 
                /// <b>Example:</b>
                /// <para>b72425bd-7871-4050-838e-033d80d754b7</para>
                /// </summary>
                [NameInMap("JobId")]
                [Validation(Required=false)]
                public string JobId { get; set; }

                /// <summary>
                /// <para>The scheduled dialing time. The value is a UNIX timestamp in milliseconds.</para>
                /// 
                /// <b>Example:</b>
                /// <para>1579068424883</para>
                /// </summary>
                [NameInMap("PlanedTime")]
                [Validation(Required=false)]
                public long? PlanedTime { get; set; }

                /// <summary>
                /// <para>The actual ringing duration.</para>
                /// 
                /// <b>Example:</b>
                /// <para>25</para>
                /// </summary>
                [NameInMap("RealRingingDuration")]
                [Validation(Required=false)]
                public long? RealRingingDuration { get; set; }

                /// <summary>
                /// <para>The ringing duration.</para>
                /// 
                /// <b>Example:</b>
                /// <para>25</para>
                /// </summary>
                [NameInMap("RingingDuration")]
                [Validation(Required=false)]
                public long? RingingDuration { get; set; }

                /// <summary>
                /// <para>The scenario ID.</para>
                /// 
                /// <b>Example:</b>
                /// <para>ade80092-03d9-4f4d-ad4f-ab8a247d3150</para>
                /// </summary>
                [NameInMap("ScenarioId")]
                [Validation(Required=false)]
                public string ScenarioId { get; set; }

                /// <summary>
                /// <para>The SIP status code of the call task.</para>
                /// 
                /// <b>Example:</b>
                /// <para>200</para>
                /// </summary>
                [NameInMap("SipCode")]
                [Validation(Required=false)]
                public string SipCode { get; set; }

                /// <summary>
                /// <para><b>[Deprecated]</b> The SIP signaling duration.</para>
                /// 
                /// <b>Example:</b>
                /// <para>25</para>
                /// </summary>
                [NameInMap("SipDuration")]
                [Validation(Required=false)]
                public long? SipDuration { get; set; }

                /// <summary>
                /// <para>The task status. Valid values:
                /// Note: The <b>Succeeded</b> status is subdivided into specific reasons. The general <b>Succeeded</b>: 1 (Connected) status is no longer returned. Instead, specific subdivided reasons are returned.</para>
                /// <list type="bullet">
                /// <item><description><b>Executing</b>: 0 (Dialing).</description></item>
                /// <item><description><b>Succeeded</b>: 1 (Connected).</description></item>
                /// <item><description><b>NoAnswer</b>: 2 (Not connected - No answer).</description></item>
                /// <item><description><b>NotExist</b>: 3 (Not connected - Nonexistent number).</description></item>
                /// <item><description><b>Busy</b>: 4 (Not connected - Busy).</description></item>
                /// <item><description><b>Cancelled</b>: 5 (Not dialed - Task stopped).</description></item>
                /// <item><description><b>Failed</b>: 6 (Failed).</description></item>
                /// <item><description><b>NotConnected</b>: 7 (Not connected - Unreachable).</description></item>
                /// <item><description><b>PoweredOff</b>: 8 (Not connected - Powered off).</description></item>
                /// <item><description><b>OutOfService</b>: 9 (Not connected - Out of service).</description></item>
                /// <item><description><b>InArrears</b>: 10 (Not connected - Overdue payment).</description></item>
                /// <item><description><b>EmptyNumber</b>: 11 (Not dialed - Nonexistent number, not dialed).</description></item>
                /// <item><description><b>PerDayCallCountLimit</b>: 12 (Not dialed - Daily limit exceeded).</description></item>
                /// <item><description><b>ContactBlockList</b>: 13 (Not dialed - Blacklisted).</description></item>
                /// <item><description><b>CallerNotRegistered</b>: 14 (Not dialed - Calling number not registered).</description></item>
                /// <item><description><b>Terminated</b>: 15 (Not dialed - Terminated).</description></item>
                /// <item><description><b>VerificationCancelled</b>: 16 (Not dialed - Canceled due to pre-call verification failure).</description></item>
                /// <item><description><b>OutOfServiceNoCall</b>: 17 (Not dialed - Out of service, not dialed).</description></item>
                /// <item><description><b>InArrearsNoCall</b>: 18 (Not dialed - Overdue payment, not dialed).</description></item>
                /// <item><description><b>CallingNumberNotExist</b>: 19 (Not dialed - Calling number does not exist).</description></item>
                /// <item><description><b>SucceededFinish</b>: 20 (Connected - Normal completion).</description></item>
                /// <item><description><b>SucceededChatbotHangUpAfterNoAnswer</b>: 21 (Connected - Robot hung up after unrecognized input).</description></item>
                /// <item><description><b>SucceededChatbotHangUpAfterSilence</b>: 22 (Connected - Robot hung up after silence timeout).</description></item>
                /// <item><description><b>SucceededClientHangUpAfterNoAnswer</b>: 23 (Connected - User hung up after unrecognized input).</description></item>
                /// <item><description><b>SucceededClientHangUp</b>: 24 (Connected - User hung up without reason).</description></item>
                /// <item><description><b>SucceededTransferByIntent</b>: 25 (Connected - Transferred to human agent due to intent match).</description></item>
                /// <item><description><b>SucceededTransferAfterNoAnswer</b>: 26 (Connected - Transferred to human agent after unrecognized input).</description></item>
                /// <item><description><b>SucceededInoInterAction</b>: 27 (Connected - No interaction from the user).</description></item>
                /// <item><description><b>SucceededError</b>: 28 (Connected - Interrupted by system error).</description></item>
                /// <item><description><b>SucceededSpecialInterceptVoiceAssistant</b>: 29 (Connected - Special interception - Voice assistant).</description></item>
                /// <item><description><b>SucceededSpecialInterceptExtensionNumberTransfer</b>: 30 (Connected - Special interception - Extension transfer).</description></item>
                /// <item><description><b>SucceededSpecialInterceptCustomSpecialIntercept</b>: 31 (Connected - Special interception - Custom interception).</description></item>
                /// <item><description><b>HighRiskSipCode</b>: 32 (Not dialed - High risk, not dialed).</description></item>
                /// </list>
                /// 
                /// <b>Example:</b>
                /// <para>SucceededTransferByIntent</para>
                /// </summary>
                [NameInMap("Status")]
                [Validation(Required=false)]
                public string Status { get; set; }

                /// <summary>
                /// <para>The call ID.</para>
                /// 
                /// <b>Example:</b>
                /// <para>ff44709e-39a6-43ba-959b-20fcabe3e496</para>
                /// </summary>
                [NameInMap("TaskId")]
                [Validation(Required=false)]
                public string TaskId { get; set; }

                /// <summary>
                /// <para>The total call duration.</para>
                /// 
                /// <b>Example:</b>
                /// <para>10</para>
                /// </summary>
                [NameInMap("TotalDuration")]
                [Validation(Required=false)]
                public long? TotalDuration { get; set; }

            }

        }

        /// <summary>
        /// <para>The API response message.</para>
        /// 
        /// <b>Example:</b>
        /// <para>Success</para>
        /// </summary>
        [NameInMap("Message")]
        [Validation(Required=false)]
        public string Message { get; set; }

        /// <summary>
        /// <para>The request ID.</para>
        /// 
        /// <b>Example:</b>
        /// <para>254EB995-DEDF-48A4-9101-9CA5B72FFBCC</para>
        /// </summary>
        [NameInMap("RequestId")]
        [Validation(Required=false)]
        public string RequestId { get; set; }

        /// <summary>
        /// <para>Indicates whether the request is successful.</para>
        /// 
        /// <b>Example:</b>
        /// <para>true</para>
        /// </summary>
        [NameInMap("Success")]
        [Validation(Required=false)]
        public bool? Success { get; set; }

    }

}
